const input = $input.first().json.body ?? $input.first().json;
const errors = [];

const domainRegex =
  /^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
if (!input.domain || !domainRegex.test(input.domain)) {
  errors.push("Invalid or missing domain.");
}

if (!Array.isArray(input.routes) || input.routes.length === 0) {
  errors.push("At least one route is required.");
}

const pathRegex = /^\/[a-zA-Z0-9_\-\/]*$/;
const fsPathRegex = /^\/[a-zA-Z0-9_\-\/.]*$/;
const seenPaths = new Set();

(input.routes || []).forEach((route, i) => {
  if (!route.path || !pathRegex.test(route.path) || route.path.includes("..")) {
    errors.push(`Route ${i}: invalid path "${route.path}".`);
  } else if (seenPaths.has(route.path)) {
    errors.push(`Route ${i}: duplicate path "${route.path}".`);
  } else {
    seenPaths.add(route.path);
  }

  if (route.type === "proxy") {
    const port = Number(route.port);
    if (!Number.isInteger(port) || port < 1 || port > 65535) {
      errors.push(`Route ${i}: invalid port "${route.port}".`);
    }
  } else if (route.type === "static") {
    if (
      !route.filesystemPath ||
      !fsPathRegex.test(route.filesystemPath) ||
      route.filesystemPath.includes("..")
    ) {
      errors.push(
        `Route ${i}: invalid filesystem path "${route.filesystemPath}".`,
      );
    }
  } else {
    errors.push(`Route ${i}: unknown type "${route.type}".`);
  }
});

// --- Custom (raw) nginx config block — user-provided, entered at their own risk ---
const customConfig =
  typeof input.customConfig === "string" ? input.customConfig.trim() : "";
const MAX_CUSTOM_CONFIG_LENGTH = 20000;
if (customConfig.length > MAX_CUSTOM_CONFIG_LENGTH) {
  errors.push(
    `Custom config exceeds maximum length of ${MAX_CUSTOM_CONFIG_LENGTH} characters.`,
  );
}
// basic brace-balance sanity check to catch obviously broken snippets early
// (this is NOT a security check, just a syntax sanity check)
const openBraces = (customConfig.match(/{/g) || []).length;
const closeBraces = (customConfig.match(/}/g) || []).length;
if (customConfig && openBraces !== closeBraces) {
  errors.push("Custom config has unbalanced curly braces.");
}


const useCloudflare = input.useCloudflare === true;
const allowNginxRootAccess = input.allowNginxRootAccess === true;

return [
  {
    json: {
      valid: errors.length === 0,
      errors,
      domain: input.domain,
      serverAddress: input.serverAddress,
      routes: input.routes,
      customConfig,
      useCloudflare,
      enableSSL: input.enableSSL,
      allowNginxRootAccess,
      sslEmail: input.sslEmail,
    },
  },
];

const { domain, routes, customConfig, useCloudflare, cloudflare_api_key } = $input.first().json;

function generateLocationBlock(route) {
  if (route.type === 'proxy') {
    return `    location ${route.path} {
        proxy_pass http://127.0.0.1:${route.port};
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }`;
  }

  if (route.type === 'static') {
    return `    location ${route.path} {
        alias ${route.filesystemPath};
        index index.html;
        try_files $uri $uri/ =404;
    }`;
  }

  throw new Error(`Unknown route type: ${route.type}`);
}

const locationBlocks = routes.map(generateLocationBlock).join('\n\n');

// Raw config the user typed manually (advanced / unvalidated, use at own risk).
// Indented and appended inside the server block, after the generated routes.
const customBlock = customConfig
  ? '\n\n    # --- Custom config (user-provided, unvalidated) ---\n' +
    customConfig.split('\n').map(line => '    ' + line).join('\n')
  : '';

const serverBlock = `server {
    listen 80;
    server_name ${domain};

${locationBlocks}${customBlock}
}
`;

return [{
  json: {
    domain,
    nginxConfig: serverBlock,
    useCloudflare,
    cloudflare_api_key
  }
}];

