=<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <title>Nginx route configuration</title>
    <style>
      :root {
        --border: #d8d5cc;
        --border-strong: #b8b4a8;
        --text-primary: #1f1e1c;
        --text-secondary: #6b6a63;
        --surface-1: #f7f6f2;
        --surface-2: #ffffff;
        --accent: #b8532f;
        --danger: #b0392f;
        --radius: 8px;
      }
      * {
        box-sizing: border-box;
      }
      body {
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background: var(--surface-1);
        color: var(--text-primary);
        max-width: 760px;
        margin: 0 auto;
        padding: 2.5rem 1.5rem 4rem;
        line-height: 1.5;
      }
      h1 {
        font-size: 20px;
        font-weight: 600;
        margin: 0 0 0.25rem;
      }
      .subtitle {
        color: var(--text-secondary);
        font-size: 14px;
        margin: 0 0 1.75rem;
      }
      label {
        display: block;
        font-size: 13px;
        color: var(--text-secondary);
        margin-bottom: 4px;
      }
      input,
      select,
      textarea {
        width: 100%;
        padding: 8px 10px;
        border: 1px solid var(--border);
        border-radius: var(--radius);
        font-size: 14px;
        background: var(--surface-2);
        color: var(--text-primary);
        font-family: inherit;
      }
      textarea {
        font-family: "SFMono-Regular", Consolas, monospace;
        font-size: 13px;
        min-height: 140px;
        resize: vertical;
      }
      input:focus,
      select:focus,
      textarea:focus {
        outline: none;
        border-color: var(--accent);
        box-shadow: 0 0 0 2px rgba(184, 83, 47, 0.15);
      }
      .field-error {
        border-color: var(--danger) !important;
      }
      .error-msg {
        color: var(--danger);
        font-size: 12px;
        margin-top: 3px;
        min-height: 14px;
      }

      .domain-block {
        background: var(--surface-2);
        border: 1px solid var(--border);
        border-radius: 12px;
        padding: 1rem 1.25rem;
        margin-bottom: 1.5rem;
      }

      .route-card {
        background: var(--surface-2);
        border: 1px solid var(--border);
        border-radius: 12px;
        padding: 1rem 1.25rem;
        margin-bottom: 0.85rem;
        position: relative;
      }
      .route-card-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 0.75rem;
      }
      .route-card-header span {
        font-size: 13px;
        font-weight: 600;
        color: var(--text-secondary);
      }
      .remove-btn {
        background: none;
        border: none;
        color: var(--danger);
        font-size: 13px;
        cursor: pointer;
        padding: 2px 6px;
      }
      .remove-btn:hover {
        text-decoration: underline;
      }

      .field-row {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0.75rem;
        margin-bottom: 0.75rem;
      }
      .field {
        margin-bottom: 0;
      }

      .add-btn {
        width: 100%;
        padding: 10px;
        border: 1px dashed var(--border-strong);
        border-radius: var(--radius);
        background: transparent;
        color: var(--text-secondary);
        font-size: 14px;
        cursor: pointer;
        margin-bottom: 1.5rem;
      }
      .add-btn:hover {
        border-color: var(--accent);
        color: var(--accent);
      }

      .advanced-block {
        background: var(--surface-2);
        border: 1px solid var(--border);
        border-radius: 12px;
        padding: 1rem 1.25rem;
        margin-bottom: 1.5rem;
      }
      .advanced-block + .advanced-block {
        margin-top: -0.75rem;
      }
      .checkbox-row {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 0.25rem;
      }
      .checkbox-row input[type="checkbox"] {
        width: auto;
      }
      .checkbox-row label {
        margin-bottom: 0;
        font-size: 14px;
        color: var(--text-primary);
      }
      .warning-text {
        font-size: 12px;
        color: var(--danger);
        margin: 2px 0 10px;
      }
      .hidden {
        display: none;
      }

      .submit-row {
        display: flex;
        gap: 0.75rem;
        align-items: center;
      }
      .submit-btn {
        background: var(--accent);
        color: #fff;
        border: none;
        padding: 10px 20px;
        border-radius: var(--radius);
        font-size: 14px;
        font-weight: 600;
        cursor: pointer;
      }
      .submit-btn:hover {
        opacity: 0.92;
      }
      .submit-btn:disabled {
        opacity: 0.5;
        cursor: not-allowed;
      }
      .status {
        font-size: 13px;
      }
      .status.ok {
        color: #2f7a3d;
      }
      .status.err {
        color: var(--danger);
      }

      .preview {
        margin-top: 2rem;
      }
      .preview h2 {
        font-size: 14px;
        font-weight: 600;
        margin: 0 0 0.5rem;
      }
      pre {
        background: #1e1d1a;
        color: #e8e6de;
        padding: 1rem;
        border-radius: var(--radius);
        font-size: 12.5px;
        overflow-x: auto;
        white-space: pre-wrap;
        word-break: break-word;
      }
    </style>
  </head>
  <body>
    <h1>Nginx route configuration</h1>
    <p class="subtitle">
      Add proxy or static routes, then submit to generate and deploy the nginx
      config.
    </p>

    <div class="domain-block">
      <label for="domain">Domain / server_name</label>
      <input id="domain" type="text" placeholder="example.com" />
      <div class="error-msg" id="domain-error"></div>
    </div>
    <div class="domain-block">
      <label for="server-address">Server address</label>
      <input
        id="server-address"
        type="text"
        placeholder="203.0.113.10 or server.example.com"
      />
      <div class="error-msg" id="server-address-error"></div>
    </div>

    <div id="routes-container"></div>

    <button class="add-btn" id="add-route-btn" type="button">
      + Add route
    </button>

    <div class="advanced-block hidden" id="root-access-block">
      <p class="warning-text">
        Some filesystem paths are outside /var/www. nginx needs permission to
        access these directories.
      </p>

      <div class="checkbox-row">
        <input type="checkbox" id="root-access-confirm" />
        <label> I understand and allow nginx access to these paths </label>
      </div>
    </div>

    <div class="advanced-block">
      <div class="checkbox-row">
        <input type="checkbox" id="use-cloudflare" />
        <label for="use-cloudflare"
          >Use Cloudflare for DNS (creates/updates an A record
          automatically)</label
        >
      </div>
    </div>

    <div class="advanced-block">
      <div class="checkbox-row">
        <input type="checkbox" id="enable-ssl" />
        <label for="enable-ssl">
          Enable SSL (automatically configure HTTPS with TLS certificate)
        </label>
      </div>
      <div id="ssl-email-field" class="hidden">
        <label for="ssl-email">Certificate notification email</label>
        <input id="ssl-email" type="email" placeholder="admin@example.com" />
        <p class="warning-text">
          This email will be used to receive certificate status and renewal
          notifications.
        </p>
        <div class="error-msg" id="ssl-email-error"></div>
      </div>
    </div>

    <div class="advanced-block">
      <label for="custom-config">Custom nginx config block (advanced)</label>
      <p class="warning-text">
        This text is injected as-is into the server block and is NOT validated.
        Only use this if you know what you're doing — mistakes here can break or
        expose your server. Use at your own risk.
      </p>
      <textarea
        id="custom-config"
        placeholder="# optional raw nginx directives, e.g. extra headers, rewrites, etc."
      ></textarea>
    </div>

    <div class="submit-row">
      <button class="submit-btn" id="submit-btn" type="button">
        Generate & deploy
      </button>
      <span class="status" id="status"></span>
    </div>

    <div class="preview" id="preview-block" style="display: none">
      <h2>Response</h2>
      <pre id="preview-output"></pre>
    </div>

    <script>
      // ---- Configuration ----
      // Point this at your n8n POST webhook URL (the "Webhook Submit" node below)
      const WEBHOOK_URL = window.location.href.split("?")[0];

      // ---- State ----
      let routes = [];
      let idCounter = 0;

      const container = document.getElementById("routes-container");
      const addBtn = document.getElementById("add-route-btn");
      const submitBtn = document.getElementById("submit-btn");
      const statusEl = document.getElementById("status");
      const domainInput = document.getElementById("domain");
      const domainError = document.getElementById("domain-error");
      const serverAddressInput = document.getElementById("server-address");
      const serverAddressError = document.getElementById(
        "server-address-error",
      );

      const useCloudflareCheckbox = document.getElementById("use-cloudflare");
      const cloudflareKeyField = document.getElementById(
        "cloudflare-key-field",
      );
      const cloudflareApiKeyInput =
        document.getElementById("cloudflare-api-key");
      const cloudflareKeyError = document.getElementById(
        "cloudflare-key-error",
      );
      const customConfigInput = document.getElementById("custom-config");
      const enableSslCheckbox = document.getElementById("enable-ssl");
      const sslEmailField = document.getElementById("ssl-email-field");
      const sslEmailInput = document.getElementById("ssl-email");
      const sslEmailError = document.getElementById("ssl-email-error");
      let rootAccessAccepted = false;
      const rootAccessBlock = document.getElementById("root-access-block");
      const rootAccessCheckbox = document.getElementById("root-access-confirm");

      rootAccessCheckbox.addEventListener("change", () => {
        rootAccessAccepted = rootAccessCheckbox.checked;
      });

      enableSslCheckbox.addEventListener("change", () => {
        sslEmailField.classList.toggle("hidden", !enableSslCheckbox.checked);
        sslEmailError.textContent = "";
        sslEmailInput.classList.remove("field-error");

        if (!enableSslCheckbox.checked) {
          sslEmailInput.value = "";
        }
      });

      function addRoute() {
        routes.push({
          id: idCounter++,
          type: "proxy",
          path: "",
          port: "",
          filesystemPath: "",
        });
        render();
      }

      function removeRoute(id) {
        routes = routes.filter((r) => r.id !== id);
        render();
      }

      function updateRoute(id, field, value) {
        const route = routes.find((r) => r.id === id);
        if (route) route[field] = value;
      }

      function render() {
        container.innerHTML = "";
        routes.forEach((route, index) => {
          const card = document.createElement("div");
          card.className = "route-card";

          const isProxy = route.type === "proxy";

          card.innerHTML = `
      <div class="route-card-header">
        <span>Route ${index + 1}</span>
        <button class="remove-btn" type="button" data-remove="${route.id}">Remove</button>
      </div>
      <div class="field-row">
        <div class="field">
          <label>Type</label>
          <select data-field="type" data-id="${route.id}">
            <option value="proxy" ${isProxy ? "selected" : ""}>Proxy to backend</option>
            <option value="static" ${!isProxy ? "selected" : ""}>Static files</option>
          </select>
        </div>
        <div class="field">
          <label>Location path</label>
          <input type="text" data-field="path" data-id="${route.id}" placeholder="/api" value="${route.path}" />
          <div class="error-msg" id="path-error-${route.id}"></div>
        </div>
      </div>
${
  isProxy
    ? `
  <div class="field">
    <label>Backend port</label>
    <input type="number" data-field="port" data-id="${route.id}" placeholder="3000" value="${route.port}" min="1" max="65535" />
    <div class="error-msg" id="port-error-${route.id}"></div>
  </div>
`
    : `
  <div class="field">
    <label>Filesystem path</label>
    <input type="text" data-field="filesystemPath" data-id="${route.id}" placeholder="/var/www/blog" value="${route.filesystemPath}" />
    <div class="error-msg" id="fs-error-${route.id}"></div>


  </div>
`
}
    `;
          container.appendChild(card);
        });

        container.querySelectorAll("[data-remove]").forEach((btn) => {
          btn.addEventListener("click", () =>
            removeRoute(Number(btn.dataset.remove)),
          );
        });
        container.querySelectorAll("[data-field]").forEach((el) => {
          el.addEventListener("input", () => {
            const id = Number(el.dataset.id);

            updateRoute(id, el.dataset.field, el.value);

            if (el.dataset.field === "type") {
              render();
              return;
            }
            if (el.dataset.field === "filesystemPath") {
              updateRootAccessVisibility();
            }
          });
        });
      }
      container.querySelectorAll("[data-root-confirm]").forEach((el) => {
        el.addEventListener("change", () => {
          rootAccessAccepted = el.checked;
        });
      });

      addBtn.addEventListener("click", addRoute);

      function requiresRootAccess() {
        return routes.some(
          (route) =>
            route.type === "static" &&
            route.filesystemPath.trim() !== "" &&
            !route.filesystemPath.startsWith("/var/www"),
        );
      }

      function updateRootAccessVisibility() {
        const needed = requiresRootAccess();

        rootAccessBlock.classList.toggle("hidden", !needed);

        if (!needed) {
          rootAccessAccepted = false;
          rootAccessCheckbox.checked = false;
        }
      }

      // ---- Client-side validation (mirrors server-side checks) ----
      function validate() {
        let valid = true;
        document
          .querySelectorAll(".error-msg")
          .forEach((e) => (e.textContent = ""));
        document
          .querySelectorAll(".field-error")
          .forEach((e) => e.classList.remove("field-error"));

        const domain = domainInput.value.trim();
        const domainRegex =
          /^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
        if (!domainRegex.test(domain)) {
          domainError.textContent = "Enter a valid domain name.";
          domainInput.classList.add("field-error");
          valid = false;
        }

        const serverAddress = serverAddressInput.value.trim();
        if (!serverAddress) {
          serverAddressError.textContent = "Server address is required.";
          serverAddressInput.classList.add("field-error");
          valid = false;
        }

        if (routes.length === 0) {
          statusEl.textContent = "Add at least one route.";
          statusEl.className = "status err";
          valid = false;
        }

        const seenPaths = new Set();
        const pathRegex = /^\/[a-zA-Z0-9_\-\/]*$/;

        routes.forEach((route) => {
          const path = route.path.trim();
          if (!pathRegex.test(path) || path.includes("..")) {
            document.getElementById(`path-error-${route.id}`).textContent =
              "Path must start with / and contain only letters, numbers, - _ /.";
            valid = false;
          } else if (seenPaths.has(path)) {
            document.getElementById(`path-error-${route.id}`).textContent =
              "Duplicate path.";
            valid = false;
          } else {
            seenPaths.add(path);
          }

          if (route.type === "proxy") {
            const port = Number(route.port);
            if (!Number.isInteger(port) || port < 1 || port > 65535) {
              document.getElementById(`port-error-${route.id}`).textContent =
                "Port must be an integer between 1 and 65535.";
              valid = false;
            }
          } else {
            const fsPath = route.filesystemPath.trim();
            const fsRegex = /^\/[a-zA-Z0-9_\-\/.]*$/;
            if (!fsRegex.test(fsPath) || fsPath.includes("..")) {
              document.getElementById(`fs-error-${route.id}`).textContent =
                'Enter a valid absolute path with no ".." segments.';
              valid = false;
            }
            if (!fsPath.startsWith("/var/www") && !rootAccessAccepted) {
              document.getElementById(`fs-error-${route.id}`).textContent =
                "You must confirm nginx root access permission for paths outside /var/www.";
              valid = false;
            }
          }
        });

        if (enableSslCheckbox.checked) {
          const sslEmail = sslEmailInput.value.trim();
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (sslEmail && !emailRegex.test(sslEmail)) {
            sslEmailError.textContent =
              "Enter a valid email address for certificate notifications.";
            sslEmailInput.classList.add("field-error");
            valid = false;
          }
        }

        updateRootAccessVisibility();
        return valid;
      }

      submitBtn.addEventListener("click", async () => {
        if (!validate()) {
          statusEl.textContent = "Fix the errors above.";
          statusEl.className = "status err";
          return;
        }

        const payload = {
          domain: domainInput.value.trim(),
          serverAddress: serverAddressInput.value.trim(),
          routes: routes.map((r) =>
            r.type === "proxy"
              ? { type: "proxy", path: r.path.trim(), port: Number(r.port) }
              : {
                  type: "static",
                  path: r.path.trim(),
                  filesystemPath: r.filesystemPath.trim(),
                },
          ),
          customConfig: customConfigInput.value.trim(),
          useCloudflare: useCloudflareCheckbox.checked,

          enableSSL: enableSslCheckbox.checked,
          sslEmail: enableSslCheckbox.checked ? sslEmailInput.value.trim() : "",
          allowNginxRootAccess: rootAccessAccepted,
        };

        submitBtn.disabled = true;
        statusEl.textContent = "Submitting...";
        statusEl.className = "status";

        try {
          const res = await fetch(WEBHOOK_URL, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
          });
          const data = await res.json().catch(() => ({}));

          document.getElementById("preview-block").style.display = "block";
          document.getElementById("preview-output").textContent =
            JSON.stringify(data, null, 2);

          if (res.ok) {
            statusEl.textContent = "Deployed successfully.";
            statusEl.className = "status ok";
          } else {
            statusEl.textContent = "Deployment failed - see response below.";
            statusEl.className = "status err";
          }
        } catch (err) {
          statusEl.textContent = "Request failed: " + err.message;
          statusEl.className = "status err";
        } finally {
          submitBtn.disabled = false;
        }
      });

      // Start with one empty route
      addRoute();
    </script>
  </body>
</html>
